using System;
using System.Collections.Generic;
using UnityEngine;

namespace SurgicalFoundations.Procedures
{
    /// <summary>
    /// One VR procedure lab, as data (Resources/Procedures/&lt;simulationId&gt;.json, generated by
    /// Tools/Curriculum/build_procedures.py). The equipment comes from the SimReady library, the targets are points on the
    /// patient, and the steps are checked by <see cref="ProcedureRunner"/>.
    /// </summary>
    [Serializable]
    public class ProcedureDefinition
    {
        public string id;
        public string title;
        public string summary;
        /// <summary>"anaesthetised" (theatre, draped) or "awake" (local anaesthetic or no anaesthetic: they talk).</summary>
        public string patientState = "anaesthetised";
        public string patientName = "Mr Daniel Okafor";
        public List<EquipmentSpec> equipment = new List<EquipmentSpec>();
        public List<AnchorSpec> anchors = new List<AnchorSpec>();
        public List<CableSpec> cables = new List<CableSpec>();
        public List<StepSpec> steps = new List<StepSpec>();
        /// <summary>Points lost per error; a critical error fails the lab whatever the score.</summary>
        public float errorPenalty = 10f;
        public float hintPenalty = 3f;
    }

    [Serializable]
    public class EquipmentSpec
    {
        /// <summary>SimReady asset id, e.g. "instrument_scalpel_handle_a01".</summary>
        public string id;
        /// <summary>"tray" (on the instrument trolley beside the learner), "bedside" (floor, near the patient's side),
        /// "head" (floor, at the head end), "foot" (floor, at the foot end).</summary>
        public string place = "tray";
        /// <summary>Name the steps use for it; defaults to the id.</summary>
        public string key;
    }

    /// <summary>A target on the patient, in metres from the umbilicus: towards the head, towards the patient's right, out of the skin.</summary>
    [Serializable]
    public class AnchorSpec
    {
        public string name;
        public string label;
        public float cranial;
        public float right;
        public float anterior;
        public float radius = 0.06f;
    }

    /// <summary>
    /// A cable or tube: its fixed end leaves one device, its plug goes into a port on another device or onto the patient.
    /// Heights are fractions of the device's height, on the face that looks towards the learner.
    /// </summary>
    [Serializable]
    public class CableSpec
    {
        public string key;
        public string label;
        public string from;
        public float fromHeight = 0.5f;
        public float fromSide = -0.2f;
        /// <summary>Equipment key of the device it plugs into, or empty when it goes onto the patient.</summary>
        public string to;
        public float toHeight = 0.5f;
        public float toSide = 0.2f;
        /// <summary>Patient anchor name, when the cable goes onto the patient (return pad, oximeter probe, ECG leads).</summary>
        public string toAnchor;
        public string color = "#2E7BD6";
        public float length = 2.5f;
    }

    [Serializable]
    public class ChoiceSpec
    {
        public string text;
        public bool correct;
        public string feedback;
        /// <summary>For talk steps: what the patient says back.</summary>
        public string reply;
        /// <summary>Choosing this is a critical error (unsafe practice).</summary>
        public bool critical;
    }

    [Serializable]
    public class StepSpec
    {
        public string id;
        /// <summary>pick · apply · operate · plug · choose · talk · confirm</summary>
        public string type;
        public string title;
        /// <summary>The coach's explanation, shown in Guided mode or when a hint is asked for.</summary>
        public string hint;
        /// <summary>pick/apply: equipment key held; operate: equipment key of the device; plug: cable key.</summary>
        public string item;
        /// <summary>Other items that count as a wrong pick for this step (e.g. a toothed forceps for bowel).</summary>
        public List<string> wrongItems = new List<string>();
        /// <summary>apply: anchor name.</summary>
        public string target;
        /// <summary>apply: seconds to hold the item at the target.</summary>
        public float hold = 1.0f;
        /// <summary>operate: joint name (empty = any moving part), and whether it must end "open" or "closed".</summary>
        public string joint;
        public bool open = true;
        /// <summary>choose/talk: the question (choose) or the patient's line (talk).</summary>
        public string prompt;
        public List<ChoiceSpec> choices = new List<ChoiceSpec>();
        /// <summary>A mistake at this step is critical (e.g. wrong-site surgery, balloon inflated in the urethra).</summary>
        public bool critical;
    }
}
